package com.digitalbase.ticketing.repository;import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.model.Ticket;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.JpaSpecificationExecutor; // 👈 ဤ Import ကို ထပ်ဖြည့်ပါimport org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import org.springframework.stereotype.Repository;import java.util.List;@Repositorypublic interface TicketRepository extends JpaRepository<Ticket, Long>, JpaSpecificationExecutor<Ticket> { // 👈 ဤနေရာတွင် JpaSpecificationExecutor ကို ထပ်ဖြည့်ပါ    // ... အခြား Method များ ...    // Developer သီးသန့် Ticket အားလုံးကို ဆွဲထုတ်ရန် (Dashboard Chart များအတွက်)    List<Ticket> findByDeveloperId(Long developerId);    List<Ticket> findAllByClientProductId(Long clientProductId);    // Status အလိုက် Ticket စုစုပေါင်း အရေအတွက် ရေတွက်ရန်    long countByCustomerIdAndStatusIn(Long customerId, java.util.List<com.digitalbase.ticketing.enums.TicketStatus> statuses);    // ယနေ့ ဝင်ထားသော Ticket များအတွက်    long countByCustomerIdAndStatusInAndCreatedAtAfter(Long customerId, java.util.List<com.digitalbase.ticketing.enums.TicketStatus> statuses, java.time.Instant startOfDay);    // ယနေ့ ပြီးဆုံးသွားသော Ticket များအတွက်    long countByCustomerIdAndStatusInAndUpdatedAtAfter(Long customerId, java.util.List<com.digitalbase.ticketing.enums.TicketStatus> statuses, java.time.Instant startOfDay);    // Developer သီးသန့် Status အလိုက် အရေအတွက်ရေတွက်ရန်    long countByDeveloperIdAndStatus(Long developerId, TicketStatus status);    // Developer ၏ သတ်မှတ်ထားသော Status နှင့် Priority (ဥပမာ CRITICAL) အလိုက် ရေတွက်ရန်    // မှတ်ချက် - သင့်စနစ်ရှိ Priority Enum အမည်ကို အသုံးပြုပါ (ဥပမာ - Priority.CRITICAL)    @Query("SELECT COUNT(t) FROM Ticket t WHERE t.developer.id = :developerId AND t.status = :status AND t.priority = 'CRITICAL'")    long countCriticalAssignedTickets(@Param("developerId") Long developerId, @Param("status") TicketStatus status);    List<Ticket> findByDeveloperIdAndStatus(Long developerId, TicketStatus status);    // Developer ၏ IN_PROGRESS နှင့် ON_HOLD နှစ်ခုလုံးကို ဆွဲထုတ်ရန်    List<Ticket> findByDeveloperIdAndStatusIn(Long developerId, java.util.List<TicketStatus> statuses);}